// Auto-embedded binary fallbacks so PWA icons and favicons never 404 in any production deployment
export interface EmbeddedAsset {
  contentType: string;
  buffer: Buffer;
}

const RAW_ASSETS: Array<[string, string, string]> = [
  ["/icons/pwa/pwa-192x192.png", "image/png", ""],
  ["/icons/pwa/pwa-512x512.png", "image/png", ""],
  ["/icons/pwa/pwa-maskable-192x192.png", "image/png", ""],
  ["/icons/pwa/pwa-maskable-512x512.png", "image/png", ""],
  ["/icons/pwa/badge-72x72.png", "image/png", ""],
  ["/icons/apple/apple-touch-icon.png", "image/png", ""],
  ["/icons/seo/favicon-192x192.png", "image/png", ""],
  ["/icons/favicon/favicon-32x32.png", "image/png", ""],
  ["/icons/favicon/favicon-16x16.png", "image/png", ""],
  ["/icons/favicon/icon.svg", "image/svg+xml", ""],
  ["/favicon.ico", "image/x-icon", ""],
];

export const PWA_ICON_FALLBACKS: Record<string, EmbeddedAsset> = Object.fromEntries(
  RAW_ASSETS.map(([route, contentType, base64]) => [
    route,
    { contentType, buffer: Buffer.from(base64, "base64") },
  ])
);
